import typing

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class AntispamMethods(BaseClient):
    """
    Методы группы 'Антиспам' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=85)
    @tracer.start_as_current_span("antispam.rapi_reportAbuse")
    def rapi_reportAbuse(
        self,
        reason: typing.Literal["spam", "porno", "violation", "other"],
        context_json: dict,
    ):
        """
        Пожаловаться на сообщение в чате
        """
        context_json["reason"] = reason

        return self.post(
            "rapi/reportAbuse",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": context_json,
            },
        )
